using Confluent.Kafka;
using Microsoft.Extensions.Configuration;

public class EventPublisher
{
    private readonly IProducer<string, string> _producer;
    public EventPublisher(IConfiguration config)
    {
        var producerConfig = new ProducerConfig { BootstrapServers = config["BOOTSTRAP_SERVER"] };
        _producer = new ProducerBuilder<string, string>(producerConfig).Build();
    }
    public void Publish(string topic, object evt)
    {
        var json = System.Text.Json.JsonSerializer.Serialize(evt);
        _producer.Produce(topic, new Message<string, string> { Value = json });
    }
}
